(4772586, 689026, 93760, '<td valign="top">I like the way you thougt outside the box. Very creative.</td>', 'I like the way you thougt outside the box. Very creative.', '2008-06-17 11:05:34.000000', NULL, 1),
(4772653, 688941, 51167, '<td valign="top">My favorite picture of the challenge.  Love the colors on this.  The orange works really great!  Still trying to figure out what they are... I eat a lot of sushi so I''m just picturing fish eggs.</td>', 'My favorite picture of the challenge.  Love the colors on this.  The orange works really great!  Still trying to figure out what they are... I eat a lot of sushi so I''m just picturing fish eggs.', '2008-06-17 11:56:41.000000', NULL, 1),
(4772656, 688032, 51167, '<td valign="top">What does this picture justice is the fly.  It made me laugh.  Just the lizard itself I don''t think I would have scored it as high.  The fly adds it all to this.  What may have been funnier is if you took off a wing or it''s head and put it in the lizards mouth.</td>', 'What does this picture justice is the fly.  It made me laugh.  Just the lizard itself I don''t think I would have scored it as high.  The fly adds it all to this.  What may have been funnier is if you took off a wing or it''s head and put it in the lizards mouth.', '2008-06-17 11:58:34.000000', NULL, 1),
(4772700, 688941, 30791, '<td valign="top">wow i love the creativity and makeup<br/>adding to fav''s good luck</td>', 'wow i love the creativity and makeupadding to fav''s good luck', '2008-06-17 12:29:12.000000', NULL, 1),
(4772708, 689043, 30791, '<td valign="top">funny concept 7</td>', 'funny concept 7', '2008-06-17 12:34:53.000000', NULL, 1),
(4772714, 688972, 90387, '<td valign="top">I think the color and lighting on this are perfect!  Very realistic, yet dramatic.  Shouldn''t it be the husband dead on the floor :-)</td>', 'I think the color and lighting on this are perfect!  Very realistic, yet dramatic.  Shouldn''t it be the husband dead on the floor :-)', '2008-06-17 12:42:43.000000', NULL, 1),
(4772718, 688796, 90387, '<td valign="top">That''s great!! Gotta be the worst part of being a mounted officer!</td>', 'That''s great!! Gotta be the worst part of being a mounted officer!', '2008-06-17 12:44:33.000000', NULL, 1),
(4772723, 689026, 90387, '<td valign="top">The most original thing I''ve seen in the challenge so far!!  I love the scene photos and particularly the footprints. Even the lighting looks harsh like a lineup. Brilliant work!</td>', 'The most original thing I''ve seen in the challenge so far!!  I love the scene photos and particularly the footprints. Even the lighting looks harsh like a lineup. Brilliant work!', '2008-06-17 12:46:36.000000', NULL, 1),
(4772728, 688941, 73235, '<td valign="top">I like your choice of the shallow DOF and the high contrast</td>', 'I like your choice of the shallow DOF and the high contrast', '2008-06-17 12:49:21.000000', NULL, 1),
(4772739, 688211, 73235, '<td valign="top">good job in diffusing the light to avoid blown out areas. also well done in your PP to have it look natural (no overssaturation as seen very often here).</td>', 'good job in diffusing the light to avoid blown out areas. also well done in your PP to have it look natural (no overssaturation as seen very often here).', '2008-06-17 12:52:03.000000', NULL, 1),
