(4778070, 689043, 93538, '<td valign="top">Very humorous</td>', 'Very humorous', '2008-06-20 17:28:15.000000', NULL, 1),
(4778072, 688857, 93538, '<td valign="top">The color tones in this photo really lend to the feeling of the scene. I really like this one.</td>', 'The color tones in this photo really lend to the feeling of the scene. I really like this one.', '2008-06-20 17:28:59.000000', NULL, 1),
(4778074, 688789, 93538, '<td valign="top">Gas prices seem to be a common theme... must of been on a lot of people''s minds for this challenge, but at least this one had some imagination.</td>', 'Gas prices seem to be a common theme... must of been on a lot of people''s minds for this challenge, but at least this one had some imagination.', '2008-06-20 17:30:27.000000', NULL, 1),
