(4778156, 688868, 93793, '<td valign="top">Well, I am in the contest but I cannot resist and I must vote and comment. Great idea, great photo. Good luck!!!</td>', 'Well, I am in the contest but I cannot resist and I must vote and comment. Great idea, great photo. Good luck!!!', '2008-06-20 18:35:41.000000', NULL, 1),
(4778366, 689079, 58457, '<td valign="top">I had a similar idea to this, but didn''t do this challenge.  I think yours is the best of the "stolen cookie" theme.  good eyes, lights, composition, and story telling.</td>', 'I had a similar idea to this, but didn''t do this challenge.  I think yours is the best of the "stolen cookie" theme.  good eyes, lights, composition, and story telling.', '2008-06-20 19:58:46.000000', NULL, 1),
(4778368, 688915, 58457, '<td valign="top">humorous for sure... I like the bit of coke under the crushed can indicating the spilled blood or guts.  This could be a magazine ad.</td>', 'humorous for sure... I like the bit of coke under the crushed can indicating the spilled blood or guts.  This could be a magazine ad.', '2008-06-20 19:58:49.000000', NULL, 1),
(4778370, 689016, 58457, '<td valign="top">I''d love to know your processing steps to get that old film print coloring.</td>', 'I''d love to know your processing steps to get that old film print coloring.', '2008-06-20 19:58:51.000000', NULL, 1),
(4778376, 688885, 58457, '<td valign="top">the composition is a bit convoluted but I LOVE the detail you captured in the flames.</td>', 'the composition is a bit convoluted but I LOVE the detail you captured in the flames.', '2008-06-20 19:59:32.000000', NULL, 1),
(4778381, 688991, 58457, '<td valign="top">almost too much detail here--interesting composition, but so much going on.  Probably would be much better viewed at full size.  kudos for the setup.</td>', 'almost too much detail here--interesting composition, but so much going on.  Probably would be much better viewed at full size.  kudos for the setup.', '2008-06-20 20:00:35.000000', NULL, 1),
(4778384, 688810, 58457, '<td valign="top">nice that you found such and interesting image in such an unassuming place.  I don''t think I would''ve looked up to take this photo--good eye, and it inspires me to keep my eyes open.</td>', 'nice that you found such and interesting image in such an unassuming place.  I don''t think I would''ve looked up to take this photo--good eye, and it inspires me to keep my eyes open.', '2008-06-20 20:00:43.000000', NULL, 1),
(4778386, 688517, 58457, '<td valign="top">very cute idea, and your angle/perspective is spot on for this shot.  it really tells a story.</td>', 'very cute idea, and your angle/perspective is spot on for this shot.  it really tells a story.', '2008-06-20 20:01:24.000000', NULL, 1),
(4778388, 688154, 58457, '<td valign="top">gruesome!</td>', 'gruesome!', '2008-06-20 20:01:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4778390, 689026, 58457, '<td valign="top">humorous.. If I''m being nitpicky, I''d say there are too many shadows... lineups tend to have that glaring look to them...</td>', 'humorous.. If I''m being nitpicky, I''d say there are too many shadows... lineups tend to have that glaring look to them...', '2008-06-20 20:01:37.000000', NULL, 1),
(4778399, 688972, 58457, '<td valign="top">Decent perspective/angle.  Definitely losing detail because of the high contrast, which I think was intentional, but I think some of your story might get lost compared w/ similar photos in this challenge. 6.</td>', 'Decent perspective/angle.  Definitely losing detail because of the high contrast, which I think was intentional, but I think some of your story might get lost compared w/ similar photos in this challenge. 6.', '2008-06-20 20:03:07.000000', NULL, 1),
(4778402, 689034, 58457, '<td valign="top">dark, moody and I like that the greens put detail in the BG.</td>', 'dark, moody and I like that the greens put detail in the BG.', '2008-06-20 20:03:53.000000', NULL, 1),
(4778406, 688876, 58457, '<td valign="top">this capture in this challenge reminds me of "American Pyscho".  You''ve got a pretty nefarious criminal here--suffocates AND shoots his victim.</td>', 'this capture in this challenge reminds me of "American Pyscho".  You''ve got a pretty nefarious criminal here--suffocates AND shoots his victim.', '2008-06-20 20:04:46.000000', NULL, 1),
(4778407, 689035, 58457, '<td valign="top">i almost did this same scene, but i didn''t have a cookie jar and i did have a portrait of 2 people!</td>', 'i almost did this same scene, but i didn''t have a cookie jar and i did have a portrait of 2 people!', '2008-06-20 20:04:50.000000', NULL, 1),
(4778409, 688807, 58457, '<td valign="top">such a typical scene--many parents can relate.</td>', 'such a typical scene--many parents can relate.', '2008-06-20 20:05:09.000000', NULL, 1),
(4778419, 688809, 58457, '<td valign="top">well this one is pretty gloomy.  I think maybe it would score higher for me if it wasn''t so well lit--I mean your suicide here is so perfectly lit that it rings of the set up.  Maybe not such nice lighting and B&amp;W, or high contrast, or high ISO to get some grain to make this a little grittier.  6 from me.</td>', 'well this one is pretty gloomy.  I think maybe it would score higher for me if it wasn''t so well lit--I mean your suicide here is so perfectly lit that it rings of the set up.  Maybe not such nice lighting and B&W, or high contrast, or high ISO to get some grain to make this a little grittier.  6 from me.', '2008-06-20 20:06:49.000000', NULL, 1),
(4778421, 688304, 58457, '<td valign="top">I think I''d like it better w/o the tape and if it were at night...</td>', 'I think I''d like it better w/o the tape and if it were at night...', '2008-06-20 20:06:52.000000', NULL, 1),
(4778425, 688971, 58457, '<td valign="top">not sure how I feel about this one... I don''t think I''d even notice the floating guy if it weren''t in this challenge, and I felt like I had to look for the "crime scene" .... so I guess the story ends up a bit confusing.  did he commit suicide?  maybe the title confuses me too.....hmmmm...otherwise, its a pretty landscape!</td>', 'not sure how I feel about this one... I don''t think I''d even notice the floating guy if it weren''t in this challenge, and I felt like I had to look for the "crime scene" .... so I guess the story ends up a bit confusing.  did he commit suicide?  maybe the title confuses me too.....hmmmm...otherwise, its a pretty landscape!', '2008-06-20 20:07:29.000000', NULL, 1),
(4778429, 688803, 58457, '<td valign="top">good thing you have that old camera--you knew you hung on to it for a reason!  Do you ever shoot w/ it?  Just wondering.  I like the B&amp;W treatment you gave this.</td>', 'good thing you have that old camera--you knew you hung on to it for a reason!  Do you ever shoot w/ it?  Just wondering.  I like the B&W treatment you gave this.', '2008-06-20 20:08:15.000000', NULL, 1),
(4778431, 688104, 58457, '<td valign="top">This fingerprint looks great, but the hand is a bit funky colored</td>', 'This fingerprint looks great, but the hand is a bit funky colored', '2008-06-20 20:08:55.000000', NULL, 1),
(4778436, 689066, 58457, '<td valign="top">came back for a second look--didn''t notice the body the first time.  I think that makes it better.  I like that the bullet is so crisp, but I think I''d like to see the gloves a little more clearly.</td>', 'came back for a second look--didn''t notice the body the first time.  I think that makes it better.  I like that the bullet is so crisp, but I think I''d like to see the gloves a little more clearly.', '2008-06-20 20:10:54.000000', NULL, 1),
(4778437, 689082, 58457, '<td valign="top">It an okay photo of a shoe, and I like b&amp;w, but I feel like w/o your title it doesn''t really tell a story.</td>', 'It an okay photo of a shoe, and I like b&w, but I feel like w/o your title it doesn''t really tell a story.', '2008-06-20 20:11:28.000000', NULL, 1),
(4778438, 688941, 58457, '<td valign="top">this is interesting, but I don''t get the title...  what are those little beads supposed to represent?  poison, boils?  Sorry that I don''t get it... good lighting though!</td>', 'this is interesting, but I don''t get the title...  what are those little beads supposed to represent?  poison, boils?  Sorry that I don''t get it... good lighting though!', '2008-06-20 20:11:31.000000', NULL, 1),
(4778439, 688786, 58457, '<td valign="top">humor definitely scores you some points.... the image is super noisy though, did you maybe not have very much light?  by your lens are you shooting w/ a sony? (that looks like a minolta maxxum lens)</td>', 'humor definitely scores you some points.... the image is super noisy though, did you maybe not have very much light?  by your lens are you shooting w/ a sony? (that looks like a minolta maxxum lens)', '2008-06-20 20:11:33.000000', NULL, 1),
(4778440, 689040, 58457, '<td valign="top">very video gamey and you did quite a bit of set up... I hope you are working on a zombie movie--if not thats a lotta make up for this!  I think though that your composition may be a bit hurt by how centered your character is (now if you were purposefully doing that to mimic a video game then in makes sense)</td>', 'very video gamey and you did quite a bit of set up... I hope you are working on a zombie movie--if not thats a lotta make up for this!  I think though that your composition may be a bit hurt by how centered your character is (now if you were purposefully doing that to mimic a video game then in makes sense)', '2008-06-20 20:11:35.000000', NULL, 1),
(4778441, 689064, 58457, '<td valign="top">Kinda dark and spooky until I read your title and then the graffiti on the building, then it just became funny.  sorry, I''m immature!</td>', 'Kinda dark and spooky until I read your title and then the graffiti on the building, then it just became funny.  sorry, I''m immature!', '2008-06-20 20:12:59.000000', NULL, 1),
(4778442, 687967, 58457, '<td valign="top">Your setup was good enough, that I don''t know that you had to include the card... not sure how I feel about it.</td>', 'Your setup was good enough, that I don''t know that you had to include the card... not sure how I feel about it.', '2008-06-20 20:13:03.000000', NULL, 1),
(4778445, 689004, 58457, '<td valign="top">i like the sharpness of the hairs on the left side of the brush, but the lighting is a bit harsh on the wooden part of it--I''m thinking maybe because you had to go high contrast for the prints--maybe masking it back if that was possible or perhaps it was your intention...</td>', 'i like the sharpness of the hairs on the left side of the brush, but the lighting is a bit harsh on the wooden part of it--I''m thinking maybe because you had to go high contrast for the prints--maybe masking it back if that was possible or perhaps it was your intention...', '2008-06-20 20:16:37.000000', NULL, 1),
(4778446, 687632, 58457, '<td valign="top">I''d like more contrast</td>', 'I''d like more contrast', '2008-06-20 20:16:43.000000', NULL, 1),
(4778448, 687293, 58457, '<td valign="top">There just isn''t enough going on here to make it really that interesting.  I guess I like the b&amp;w, but I need more.</td>', 'There just isn''t enough going on here to make it really that interesting.  I guess I like the b&w, but I need more.', '2008-06-20 20:17:32.000000', NULL, 1),
(4778449, 688953, 58457, '<td valign="top">who is undercover--the photographer?  the person behind the lens?  certainly not those cops in yellow!  I guess I don''t get it.</td>', 'who is undercover--the photographer?  the person behind the lens?  certainly not those cops in yellow!  I guess I don''t get it.', '2008-06-20 20:18:12.000000', NULL, 1),
(4778450, 688230, 58457, '<td valign="top">i bet it was piglet.</td>', 'i bet it was piglet.', '2008-06-20 20:18:18.000000', NULL, 1),
